mapper.select:
SELECT COUNT(*)
WHERE b.scope = 'PUBLIC' AND b.status = 'VISIBLE'
AND b.category_id = #{categoryId}

SELECT
WHERE b.scope = 'PRIVATE' AND b.owner_id = #{ownerId}
ORDER BY b.updated_at DESC, b.id DESC

SELECT
JOIN reader_access_request r ON r.book_id = b.id WHERE b.scope = 'PRIVATE' AND r.requester_id = #{viewerId} AND r.status = 'APPROVED' AND b.owner_id <> #{viewerId}
ORDER BY b.updated_at DESC, b.id DESC
